	('tooltip_order_01', 0, 2011, '<size:10><#ffffcc>The player and creature attack the target at the same time.<BR>Ctr key + click on the attack target'),
	('tooltip_order_02', 0, 2012, '<size:10><#ffffcc>The selected creature attacks the target object.<BR>Alt key + click on the attack target'),
	('tooltip_order_03', 0, 2013, '<size:10><#ffffcc>Do not use.'),
	('tooltip_order_04', 0, 2014, '<size:10><#ffffcc>The creature follows you.<BR>Press ESC 3 times consecutively.'),
	('tooltip_order_05', 0, 2031, '<size:10><#ffffcc>Sit down or stand up.<BR>HP and MP are recovered more quickly when sitting down,<BR>but some other actions cannot be performed.<BR><#17f39c>/sit  /stand'),
	('tooltip_order_06', 0, 2032, '<size:10><#ffffcc>Toggle between walking and running.<BR><#17f39c>/walk /run'),
	('tooltip_order_07', 0, 2033, '<size:10><#ffffcc>Pick up the closest nearby item.'),
	('tooltip_order_08', 0, 2034, '<size:10><#ffffcc>Attack the target.'),
	('tooltip_order_09', 0, 2035, '<size:10><#ffffcc>Set the selected party member\'s target as your target.<BR>You may not use the assist function on a far away party member.<BR><#17f39c>/assist'),
	('tooltip_order_10', 0, 2036, '<size:10><#ffffcc>Turn PK mode on/off.<BR>With PK mode on, you can<BR>battle with other players.<BR><#17f39c>/PKON /PKOFF'),
	('tooltip_order_11', 0, 2037, '<size:10><#ffffcc>Mount/Dismount a summoned ridable creature.<BR>You may only use it on your own creature.<BR><#17f39c>/ride /leave'),
	('tooltip_order_12', 0, 2038, '<size:10><#ffffcc>Request to trade with another player.<BR><#17f39c>/trade'),
	('tooltip_order_13', 0, 2039, '<size:10><#ffffcc>Open a window that allows you to combine 2 or more items.<BR><#17f39c>/union'),
	('tooltip_order_14', 0, 2040, '<size:10><#ffffcc>Open a private store. You cannot open a store in Trainee Island and Ursa Caverns. And you cannot open a store during a dungeon siege or time attack.<BR><#17f39c>/shop'),
	('tooltip_order_15', 0, 2041, '<size:10><#ffffcc>Lightly wave your hand.<BR><#17f39c>/hi'),
	('tooltip_order_16', 0, 2042, '<size:10><#ffffcc>Greet formally.<BR><#17f39c>/greeting'),
	('tooltip_order_17', 0, 2043, '<size:10><#ffffcc>Smile happily.<BR><#17f39c>/laugh'),
	('tooltip_order_18', 0, 2044, '<size:10><#ffffcc>Grieve.<BR><#17f39c>/sadness'),
	('tooltip_order_19', 0, 2045, '<size:10><#ffffcc>Sincerely agree by nodding your head.<BR><#17f39c>/yes'),
	('tooltip_order_20', 0, 2046, '<size:10><#ffffcc>Firmly disagree by shaking your head.<BR><#17f39c>/no'),
	('tooltip_order_21', 0, 2047, '<size:10><#ffffcc>Express your boredom.<BR><#17f39c>/boring'),
	('tooltip_order_22', 0, 2048, '<size:10><#ffffcc>Admit your mistake and ask for forgiveness.<BR><#17f39c>/apology'),
	('tooltip_order_23', 0, 2049, '<size:10><#ffffcc>Cheer!<BR><#17f39c>/cheers'),
	('tooltip_order_24', 0, 2050, '<size:10><#ffffcc>Sulk with hurt feelings.<BR><#17f39c>/pish'),
	('tooltip_order_25', 0, 2051, '<size:10><#ffffcc>Dance excitedly to the rhythm.<BR><#17f39c>/dance'),
	('tooltip_order_26', 0, 2052, '<size:10><#ffffcc>Clap pleasantly.<BR><#17f39c>/clap'),
	('tooltip_order_27', 0, 2053, '<size:10><#ffffcc>Erupt in a violent temper.<BR><#17f39c>/rage'),
	('tooltip_order_28', 0, 2054, '<size:10><#ffffcc>Mock and sneer at someone.<BR><#17f39c>/makeangry'),
	('tooltip_order_29', 0, 2055, '<size:10><#ffffcc>Organize a party.<BR>You must enter an appropriate party name to organize a party.<BR><#17f39c>/pcreate PartyName'),
