	('name_itemtooltip_20540004', 0, 20540004, '<b><size:13>#@itemname@#</b><br><size:4><br><size:10>A card that can seal an astarot.<br><size:4><br><size:10>Weight : 0.5'),
	('name_itemtooltip_20540005', 0, 20540005, '<b><size:13>#@itemname@#</b><br><size:4><br><size:10>A card that can seal red pixie. It can tame firefly, small firewing, and fierce firewing.<br><size:4><br><size:10>Weight : 0.5'),
	('name_itemtooltip_20540006', 0, 20540006, '<b><size:13>#@itemname@#</b><br><size:4><br><size:10>A card that can seal blue pixie. It can tame blue fairy, blue crystal, and blue crystal fury.<br><size:4><br><size:10>Weight : 0.5'),
