	('name_itemtooltip_20540010', 0, 20540010, '<b><size:13>#@itemname@#</b><br><size:4><br><size:10>A card that can seal kentauros. It can tame kenta pony, crude wild hoof, and fierce aris.<br><size:4><br><size:10>Weight : 0.5'),
	('name_itemtooltip_20540011', 0, 20540011, '<b><size:13>#@itemname@#</b><br><size:4><br><size:10>A card that can seal yeti. It can tame hungry hairy eye, great hairy eye, and yeti berk.<br><size:4><br><size:10>Weight : 0.5'),
