	('name_continuouseffectooltip_004522', 0, 60004522, '<B><#99ff66>Clean Air<Chinese Earth Day><#ffffff></B><BR><size:4><br><size:10><#ffffcc>Mov. Spd increases by 10% for 15 minutes.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004523', 0, 60004523, '<B><#99ff66>Clean Water<Chinese Earth Day><#ffffff></B><BR><size:4><br><size:10><#ffffcc>M. Atk increases by 10% for 15 minutes.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004524', 0, 60004524, '<B><#99ff66>Rich Soil<Chinese Earth Day><#ffffff></B><BR><size:4><br><size:10><#ffffcc>Def. increases by 10% for 15 minutes.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004525', 0, 60004525, '<B><#99ff66>Powerful Flame<Chinese Earth Day><#ffffff></B><BR><size:4><br><size:10><#ffffcc> Atk increases by 10% for 15 minutes.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004526', 0, 60004526, '<B><#99ff66>Everlasting Love<Chinese Earth Day><#ffffff></B><BR><size:4><br><size:10><#ffffcc>Luck increases by 10% for 15 minutes.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004544', 0, 60004544, '<B><#99ff66>Easter Bread Effect<#ffffff></B><BR><size:4><br><size:10><#ffffcc>Some of the total HP will be recovered. <br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004547', 0, 60004547, '<B><#99ff66>Easter HP Recovery Liquid <#ffffff></B><BR><size:4><br><size:10><#ffffcc>Some of the total HP will be recovered. <br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004548', 0, 60004548, '<B><#99ff66>Eater MP Recovery Liquid<#ffffff></B><BR><size:4><br><size:10><#ffffcc>Some of the total MP will be recovered. <br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004549', 0, 60004549, '<B><#99ff66>Easter Turkey<#ffffff></B><BR><size:4><br><size:10><#ffffcc>Some of the total HP/MP will be recovered. <br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_005001', 0, 60005001, '<B><#99ff66>MAX HP decreases. <#ffffff></B><BR><size:4><BR><size:10><#ffffcc>Decreases a certain percentage of maximum HP.<#ffffff><BR>'),
	('name_continuouseffectooltip_005002', 0, 60005002, '<B><#99ff66>MAX MP decreases. <#ffffff></B><BR><size:4><BR><size:10><#ffffcc>Decreases a certain percentage of maximum<#ffffff><BR>'),
