	('name_continuouseffectooltip_003467', 0, 60013467, '<B><#99ff66>Panoply of the Ground <#ffffff></B><BR><size:4><BR><size:10><#ffffcc>Greatly increase the Defense Power of the caster for a moment.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_003471', 0, 60013471, '<B><#99ff66>Supplement of Sacred Fire <#ffffff></B><BR><size:4><BR><size:10><#ffffcc>Increase the Attack Power by certain %<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_003472', 0, 60013472, '<B><#99ff66>Tears of Gaia <#ffffff></B><BR><size:4><br><size:10><#ffffcc>Able to automatically resurrect if killed.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_003492', 0, 60013492, '<B><#99ff66>Holy Aura<#ffffff></B><BR><size:4><br><size:10><#ffffcc>Causes damage to nearby enemies for a certain period of time.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_003601', 0, 60013601, '<B><#99ff66>Nightmare <#ffffff></B><BR><size:4><BR><size:10><#ffffcc>Asleep, cannot attack or move. Wakes upon receiving damage.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_003602', 0, 60013602, '<B><#99ff66>Windy Shackle <#ffffff></B><BR><size:4><BR><size:10><#ffffcc>Greatly decreases attack speed.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_003604', 0, 60013604, '<B><#99ff66>Neutralization of Darkness <#ffffff></B><BR><size:4><BR><size:10><#ffffcc>P. Atk. ?? decreases<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_003608', 0, 60013608, '<B><#99ff66>Mind Crisis <#ffffff></B><BR><size:4><BR><size:10><#ffffcc>Curse Spell which Decreases target enemy\'s Magical Defense Power <br><size:4><BR><size:10><#ffffff>'),
