	('name_continuouseffectooltip_003622', 0, 60013622, '<B><#99ff66>Seal of Gaia <#ffffff></B><BR><size:4><br><size:10><#ffffcc>Unable to use summon magic.<br><size:4><BR><size:10><#ffffff>'),
