	('name_continuouseffectooltip_003754', 0, 60013754, '<B><#99ff66>Yak Advent <#ffffff></B><BR><size:4><BR><size:10><#ffffcc>Changed to a Yak, blocking Skills and weakening Attack Power and Magical Attack Power.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_003815', 0, 60013815, '<B><#99ff66>Hate Aura<#ffffff></B><BR><size:4><br><size:10><#ffffcc>Attact monster\'s attention for a while. <br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_006065', 0, 60036065, '<B><#99ff66>Sharp Claw<#ffffff></B><BR><size:4><br><size:10><#ffffcc>Increases Attack Power by 50%<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_006069', 0, 60036069, '<B><#99ff66>Seismic Wave<#ffffff></B><BR><size:4><br><size:10><#ffffcc>Decreases the movement and attack speed<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004012', 0, 60014012, '<B><#99ff66>Pass Damage <#ffffff></B><BR><size:4><BR><size:10><#ffffcc>Transfers a certain percentage of damage taken by the caster to their creature.<br><size:4><BR><size:10><#ffffff>'),
