	('name_continuouseffectooltip_004001', 0, 60164001, '<B><#99ff66>Harmony of Life<#ffffff></B><BR><size:4><br><size:10><#ffffcc>Harmonize with creature and increase your HP and MP. Unable to summon creature during the lasting time.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004002', 0, 60164002, '<B><#99ff66>Beast Disguise<#ffffff></B><BR><size:4><br><size:10><#ffffcc> Disguise as summoned creature and make itself unidentified. Moving speed is getting faster.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004202', 0, 60164202, '<B><#99ff66>Soothe Creature<#ffffff></B><BR><size:4><br><size:10><#ffffcc>Recovers HP slowly.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004204', 0, 60164204, '<B><#99ff66>Creature Restoration <#ffffff></B><BR><size:4><br><size:10><#ffffcc>Recovers HP over time<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004401', 0, 60164401, '<B><#99ff66>Strength Boost <#ffffff></B><BR><size:4><br><size:10><#ffffcc>Increases strength and attack power.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004402', 0, 60164402, '<B><#99ff66>Vitality Boost <#ffffff></B><BR><size:4><br><size:10><#ffffcc>Increases vitality and defense power.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004403', 0, 60164403, '<B><#99ff66>Intelligence Boost <#ffffff></B><BR><size:4><br><size:10><#ffffcc>Increases intelligence and magic attack power.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004404', 0, 60164404, '<B><#99ff66>Wisdom Boost <#ffffff></B><BR><size:4><br><size:10><#ffffcc>Increases wisdom and magic defense power.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004405', 0, 60164405, '<B><#99ff66>Blood Aura<#ffffff></B><BR><size:4><br><size:10><#ffffcc>Increases creature\'s attack power and HP<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004406', 0, 60164406, '<B><#99ff66>Spirit Aura <#ffffff></B><BR><size:4><br><size:10><#ffffcc>Increases creature\'s magic attack power and MP<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004407', 0, 60164407, '<B><#99ff66>Aura of Halisha<#ffffff></B><BR><size:4><br><size:10><#ffffcc>Increases all of creature\'s abilities.<br><size:4><BR><size:10><#ffffff>'),
	('name_continuouseffectooltip_004801', 0, 60164801, '<B><#99ff66>Anger of Spirit <#ffffff></B><BR><size:4><br><size:10><#ffffcc>Increased physical and magic attack power. Increased rate to resist damage over time effects.<br><size:4><BR><size:10><#ffffff>'),
