	('script_string_90010232', 0, 90010232, 'Disband alliance'),
	('script_string_90010233', 0, 90010233, 'You cannot form or join a new alliance for 7 days after the alliance is disbanded. You still want to disband the alliance?'),
	('script_string_90010234', 0, 90010234, 'Guild has been disbanded.'),
	('script_string_90010235', 0, 90010235, 'Does not belong to any alliance.'),
	('script_string_90010236', 0, 90010236, 'Cannot disband during dungeon siege or raid.'),
	('script_string_90010237', 0, 90010237, 'Only the alliance master can disband the alliance.'),
	('script_string_90010238', 0, 90010238, 'Alliance cannot be disbanded until all guilds leave the alliance.'),
	('script_string_90010239', 0, 90010239, 'Cannot disband if the alliance owns a dungeon.'),
	('script_string_90010240', 0, 90010240, 'Cannot disband while participating in a raid or seize.'),
	('script_string_90010241', 0, 90010241, 'Luna Chip'),
	('script_string_90010242', 0, 90010242, 'Rank 1 Luna Chip'),
