	('script_string_90760100', 0, 90760100, 'Merchant Rouch'),
	('script_string_90760101', 0, 90760101, '<B>Merchant Rouch</B><BR>'),
	('script_string_90760102', 0, 90760102, 'Now many items you may need for your adventure on sale so please take a look.'),
	('script_string_90760103', 0, 90760103, 'Use shops. '),
	('script_string_90760200', 0, 90760200, 'Warehouse Keeper Arisia'),
	('script_string_90760201', 0, 90760201, '<B>Warehouse Keeper Arisia</B><BR>'),
	('script_string_90760202', 0, 90760202, 'Welcome, Great Adventurer! There are many dangers in this island still unknown. Please be careful.<BR>You may keep your personal items safe in the warehouse.'),
	('script_string_90760203', 0, 90760203, 'Use warehouses. '),
	('script_string_90760300', 0, 90760300, 'Lak Trader Granchester'),
	('script_string_90760301', 0, 90760301, '<B>Lak Trader Granchester</B><BR>'),
	('script_string_90760302', 0, 90760302, 'Hello, I am Lak Trader Granchester. Hm. are you here to trade laks?  Or do you want to buy a boost chip?'),
	('script_string_90760303', 0, 90760303, 'What do you want to trade? I have Force chips, Soul chips and Luna chips.'),
	('script_string_90760304', 0, 90760304, 'You have currently  #@rac@# Lak.. So you can trade them for #@number@# force chips. How many do you want to trade?'),
	('script_string_90760400', 0, 90760400, 'Black Smith Lutein'),
	('script_string_90760401', 0, 90760401, '<B>Black Smith Lutein</B><BR>'),
	('script_string_90760402', 0, 90760402, 'Rare customer. Give me your item you want to upgrade. I will give it for cheap. I can only upgrade equipped item. '),
	('script_string_90760403', 0, 90760403, 'Rank 1 item is available up to Lv5, and items above Rank 2 are available for up to Lv10… What? You knew it? You\'re smart.Hm!'),
	('script_string_90760404', 0, 90760404, 'I can\'t upgrade this..'),
	('script_string_90760405', 0, 90760405, 'If you want to upgrade #@item_name@# Lv #@item_Lv@# into Lv#@item_up_Lv@#, it costs #@upgrade_cost@# rupee.<BR>Do you want it?'),
	('script_string_90760500', 0, 90760500, 'Merchant Graian'),
	('script_string_90760501', 0, 90760501, '<B>Merchant Graian</B><BR>'),
	('script_string_90760502', 0, 90760502, 'Hellp~ I am Graian. I have this and that. So why don’t you look around.'),
	('script_string_90760503', 0, 90760503, 'Use shops'),
	('script_string_90760600', 0, 90760600, 'Lak Trader Picartoon'),
	('script_string_90760601', 0, 90760601, '<B>Lak Trader Picartoon</B><BR>'),
	('script_string_90760602', 0, 90760602, 'I am Lak Trader Picartoon. Are you here to trade Lak? Or do you want to buy a boost chip?'),
	('script_string_90760603', 0, 90760603, 'I have force chip, soul chip, and luna chip for sale.'),
	('script_string_90760604', 0, 90760604, 'If you give me #@rac@# lak, I will trade them for #@number@# force chips. How many do you need??'),
	('script_string_90760605', 0, 90760605, 'If you give me #@rac@# lak, I will trade them for #@number@# soul chips. How many do you need??'),
	('script_string_90760606', 0, 90760606, '#@rac@# lak can be traded for #@number@# rupee. How many do you want to trade?'),
	('script_string_90760607', 0, 90760607, 'Please tell me the chip\'s rank you want.'),
	('script_string_90760609', 0, 90760609, 'If you give me #@rac@# lak, I will trade them for #@number@# luna chips.  How many do you need??'),
	('script_string_90991000', 0, 90991000, 'Abyss Manager'),
