	('script_string_90996402', 0, 90996402, 'Hi I\'m Franken, do you know how to get to Halloween Wonderland?'),
	('script_string_90996971', 0, 90996971, 'Get the Rudolph Suit!'),
	('script_string_90996975', 0, 90996975, 'Use the store.'),
	('script_string_90998001', 0, 90998001, '<B>Mystic Jewel Trader</B><BR>'),
	('script_string_90998002', 0, 90998002, 'Welcome to my Mystic Jewels shop. See anything you like?'),
